      "好家伙，这招我得偷回铁炉去。": "こいつはすげえ、その技は鉄炉に持ち帰らせてもらう。",
      "抱歉啊，我的锤子不认得轻重。": "悪いな、俺のハンマーは加減を知らねえ。",
      "对不住。要不你站远点，下次好躲。": "すまねえ。次は避けやすいように離れて立っとけ。",
      "你的盾看上去像报名处送的纪念品。": "お前の盾、受付でもらった記念品にしか見えねえな。",
      "站稳了！铁炉的锤子不打第二下。": "踏ん張れ！鉄炉のハンマーに二撃目はねえ。",
      "苍叶精灵的游侠。我画过这片大陆一半的道路。": "蒼葉エルフの遊侠だ。この大陸の道の半分は私が描いた。",
      "你好。别担心，林地公约规定我得先打招呼。": "こんにちは。安心して、林地協定で先に挨拶する決まりなの。",
      "好路线！这一步像是量过距离。": "いい経路だ！歩幅まで測ったような一手だな。",
      "漂亮。公开军校的教官会想请你去讲课。": "見事。公開軍学校の教官が講師に招きたがるぞ。",
