      "多谢。苍叶的人从不欠路费。": "どうも。蒼葉の者は通行料を借りたままにしない。",
      "这条路我的地图上可没有！": "そんな道、私の地図には載っていない！",
      "哇，得赶紧补进下一版的地图。": "わあ、次の版の地図に急いで書き足さないと。",
      "抱歉，我的援军走错了小路。": "ごめん、援軍が小道を間違えた。",
      "对不起，按公约我得赔你一次。": "すまない。協定に従って一つ借りだ。",
      "道路测绘、林地公约与公开军校——我背后是整个苍叶。": "道路測量、林地協定、公開軍学校——私の背には蒼葉がある。",
      "我知道这片战场上的每一条退路，你的也一样。": "この戦場の退路はすべて知っている。お前のもな。",
      "赤焰学院导师。今天的课题：火焰的战术化。": "赤焔学院の導師よ。本日の課題は炎の戦術化。",
      "你好。请站在标记线外，我不想把你算进爆炸半径。": "こんにちは。線の外に立って。爆発半径に入れたくないの。",
      "精彩，变量控制得非常干净。": "素晴らしい。変数の制御が実に綺麗ね。",
      "这一手可以写进下学期的教材。": "今の一手は来学期の教科書に載せられるわ。",
      "谢谢配合，数据很完整。": "ご協力ありがとう。データは完璧よ。",
