      "拒绝离开故土的大贤者。每个行动回合恢复首领和全部史莱姆生命，每3回合分裂出两名碧露近卫。": "故郷を離れることを拒む大賢者。行動ターンごとにボスとスライム全ての体力を回復し、3ターンごとに碧露の近衛を2体分裂させる。",
