      "每个敌方行动回合，为首领恢复10点生命，并为所有史莱姆随从恢复5点生命。": "敵の行動ターンごとに、ボスの体力を10、スライムのミニオン全ての体力を5回復する。",
      "碧露分裂": "碧露の分裂",
