      "封锁全部前排": "前列全体を封鎖する",
      "四位魅魔军官拒绝撤离，以20点攻击力立即展开反击；小队将被杀退，但第五关仍会按通关结算。": "4人のサキュバス士官は撤退を拒み、攻撃力20で即座に反撃する。部隊は撃退されるが、第5章はクリア扱いで精算される。",
      "四位魅魔军官没有进攻，只维持结界，为同伴撤离争取两回合。": "4人のサキュバス士官は攻撃せず、結界を維持して仲間の撤退のために2ターンを稼ぐ。",
      "千枝城反击开始：四名魅魔军官依次以20点攻击杀向小队。": "千枝城の反撃開始：4人のサキュバス士官が攻撃力20で次々と部隊に襲いかかる。",
      "四名军官的攻势击穿战线，魔族联军先遣队随即越过裂隙接管废墟；小队被迫撤出千枝城。": "4人の士官の猛攻が戦線を突破し、魔族連合軍の先遣隊が裂け目を越えて廃墟を掌握した。部隊は千枝城からの撤退を余儀なくされた。",
      "四位魅魔军官击溃了小队，但银灰狼女猎手已经被击败：第五关剧情完成，全部战利品与通关奖励照常结算。": "4人のサキュバス士官が部隊を打ち破ったが、銀灰の狼女狩人はすでに倒されている。第5章のストーリーは完了し、全ての戦利品とクリア報酬は通常どおり精算される。",
      "你的英雄倒下了。冒险结束。": "あなたのヒーローは倒れた。冒険は終わった。",
