      "第五关位于翡翠城南方的古城废墟。灰狼与其他野兽凭借速度和突袭扩张领地，最终迎战银灰狼女猎手。": "第5章は翡翠城の南にある古都の廃墟。灰狼やその他の獣が速さと奇襲で縄張りを広げている。最後に銀灰の狼女狩人と戦う。",
      "第四关拥有二十个史莱姆首领节点。她们生命厚重、攻击较低并会不断再生；沿发光溪流深入森林，最终面对碧露大贤者·涅芙莉。": "第4章にはスライムのボスノードが20ある。体力は厚く攻撃力は低く、絶えず再生する。光る渓流に沿って森の奥へ進み、最後に碧露の大賢者ネフリーと対峙する。",
      "第三关拥有二十个熊族首领节点与一处农舍。沿农田支路调查被占领的村庄，最终面对丰穗战母·布蕾娅。": "第3章には熊族のボスノードが20と農家が1軒ある。畑の小道に沿って占領された村を調べ、最後に豊穂の戦母ブレアと対峙する。",
      "第二关拥有二十个首领节点。沿着哥布林军团的防线一路推进，最终迎战拥有200生命的翠影女王。": "第2章にはボスノードが20ある。ゴブリン軍団の防衛線に沿って進み、最後に体力200の翠影の女王と戦う。",
      "在四条前后排战线上部署军队，撕开一路缺口，穿越十三个迷雾森林节点。每一次胜利，都会化为下一次远征的力量。": "前列・後列からなる4本の戦線に軍を配置し、1本の突破口をこじ開け、霧の森の13のノードを越えていけ。全ての勝利が、次の遠征の力になる。",
