      "哥布林王庭": "ゴブリン王宮",
      "迷雾森林远征": "霧の森の遠征",
      "灰狼和其他野兽速度极快，许多单位登场即可攻击。击败全部节点后，魔族联军会在废墟建立据点，之后可以反复挑战强大的军官与魔族军队。": "灰狼やその他の獣は非常に素早く、多くのユニットが場に出てすぐ攻撃できる。全てのノードを倒すと魔族連合軍が廃墟に拠点を築き、以降は強力な士官と魔族の軍勢に何度でも挑戦できる。",
      "沿发光溪流与林间小径推进。每个史莱姆首领都会治疗自身与随从；击败节点后开启所有相邻路线，首胜卡牌会在战后揭晓。": "光る渓流と林間の小道に沿って進む。スライムのボスはどれも自身とミニオンを回復する。ノードを倒すと隣接するルートが全て開き、初勝利のカードは戦闘後に明かされる。",
      "沿金色路线推进。击败节点后会开启所有相邻路线；抵达农舍旁的节点后，可与留守的农民夫妇交谈。每个首领的首胜奖励会在战后揭晓。": "金色のルートに沿って進む。ノードを倒すと隣接するルートが全て開く。農家の横のノードに着くと、残った農家の夫婦と話せる。各ボスの初勝利報酬は戦闘後に明かされる。",
      "击败任一节点即可开启相邻路线；翠影女王会在抵达右上方终点后开放。大部分节点由哥布林军团驻守。": "いずれかのノードを倒すと隣接するルートが開く。翠影の女王は右上の終点に到達すると挑戦可能になる。ほとんどのノードはゴブリン軍団が守っている。",
      "金边节点由更强的敌人驻守；首次击败会获得未知战利品。击败节点后仍可回到岔路挑战相邻路线。": "金縁のノードはより強い敵が守っている。初めて倒すと未知の戦利品を得る。ノードを倒した後も分かれ道に戻って隣接するルートに挑戦できる。",
      "击败一个节点后，所有相邻的未完成节点都会解锁。战败不会清空本关进度，切换关卡也会分别保存。": "ノードを1つ倒すと、隣接する未完了のノードが全て解放される。敗北しても章の進行度は消えず、章を切り替えてもそれぞれ保存される。",
      "⭐ 本轮": "⭐ 今回の周回",
      "⚔️ 已完成": "⚔️ 完了",
      "🛡️ 失败": "🛡️ 失敗",
      "退出当前关卡": "章から退出",
      "先抵达农舍旁的农田节点。": "先に農家の横の農地ノードへ到達してください。",
      "金麦农场 · 留守者的证言": "金麦農場・残った者たちの証言",
      "他们并不要求你放下武器，只希望你在见到丰穗战母之前，先知道这些熊族并未伤害原来的村民。": "彼らはあなたに武器を置けとは言わない。ただ豊穂の戦母に会う前に、この熊族たちが元の村人を傷つけていないことを知ってほしいだけだ。",
      "我会亲眼判断": "自分の目で判断する",
      "请先完成第五关结局，解锁千枝城魔族重建据点。": "先に第5章のエンディングをクリアして、千枝城の魔族再建拠点を解放してください。",
      "极限挑战": "極限チャレンジ",
      "千枝城驻军暂时退却": "千枝城の駐屯軍が一時撤退",
      "你击退了不可一世的魔族驻军，获得500金币。她们仍会继续重建千枝城，之后仍可再次挑战。": "傲岸不遜な魔族の駐屯軍を撃退し、500ゴールドを獲得した。彼女たちは千枝城の再建を続けており、今後も再挑戦できる。",
      "返回废墟地图": "廃墟マップに戻る",
      "魔族军官守住了据点": "魔族の士官が拠点を守り抜いた",
      "20攻/200血的驻军压倒了小队。这场失败不会重置第五关进度，也不会造成额外惩罚。": "20/200の駐屯軍が部隊を圧倒した。この敗北で第5章の進行度がリセットされることはなく、追加のペナルティもない。",
      "每一列的前排会保护其身后的后排。": "各レーンの前列は、その後ろの後列を守る。",
      "击败前排后，才能普通攻击该列后排。": "前列を倒して初めて、そのレーンの後列を通常攻撃できる。",
      "前后排全部为空时，该路线被突破。": "前列と後列が全て空になると、そのレーンは突破される。",
      "通过突破路线可以直接攻击敌方英雄。": "突破したレーンから敵のヒーローを直接攻撃できる。",
      "你的最大法力不会每回合增加。": "最大マナは毎ターン増えない。",
      "海港的统领试炼是永久提高最大法力的唯一途径。": "港の統率者の試練が、最大マナを永続的に上げる唯一の方法だ。",
      "首次战斗": "初めての戦い",
      "六条战场要诀": "戦場の6つの心得",
      "开始战斗": "戦闘開始",
      "第五关剧情完成": "第5章のストーリー完了",
      "最终胜利": "最終勝利",
      "千枝城反击战结束": "千枝城の反撃戦終了",
      "首杀固定奖励": "初撃破の確定報酬",
      "关键物品": "重要アイテム",
      "河水中的猩红丝线与古老月辉产生共鸣。它能开启统领试炼第七关。": "川の水に含まれる緋色の糸が古の月光と共鳴している。統率者の試練の第7試練を開くことができる。",
      "已收入行囊，可用于统领试炼第七关。": "荷物にしまった。統率者の試練の第7試練で使える。",
      "战斗胜利": "戦闘勝利",
      "选择一项额外奖励": "追加報酬を1つ選ぶ",
      "千枝城的旗帜重新升起": "千枝城の旗が再び翻る",
      "梦幻森林归于寂静": "夢幻の森に静寂が戻る",
      "金麦农场的战事落幕": "金麦農場の戦いが幕を下ろす",
      "哥布林王庭陷落": "ゴブリン王宮陥落",
      "密林重见曙光": "密林に再び夜明けが",
      "你击败银灰狼女猎手后，五位魅魔军官没有继续退避。她们救下狼族首领，以20点攻击的力量击溃小队，并决定在千枝城废墟建立魔族据点、重建这座千年前的共居之城。第五关奖励照常结算，英雄等级上限提升至25级；废墟地图上已经开放可反复挑战的魔族驻军。": "銀灰の狼女狩人を倒すと、5人のサキュバス士官はもう退かなかった。彼女たちは狼族の首領を救い出し、攻撃力20の力で部隊を打ち破ると、千枝城の廃墟に魔族の拠点を築き、千年前に諸族が共に暮らしたこの都を再建すると決めた。第5章の報酬は通常どおり精算され、ヒーローのレベル上限は25に上がった。廃墟マップには何度でも挑戦できる魔族の駐屯軍が解放された。",
      "你击败了碧露大贤者·涅芙莉，迫使史莱姆族群退回森林深处，并将英雄等级上限提升至20级。": "碧露の大賢者ネフリーを倒し、スライムの一族を森の奥へ退かせ、ヒーローのレベル上限を20に引き上げた。",
      "你击败了丰穗战母·布蕾娅，完成第三关并解锁东部梦幻森林与英雄20级上限。": "豊穂の戦母ブレアを倒して第3章をクリアし、東部の夢幻の森とヒーローのレベル上限20を解放した。",
      "你击败了翠影女王，完成第二关的二十场首领战，并解锁王城南部的金麦农场与英雄15级上限。": "翠影の女王を倒して第2章の20のボス戦を制し、王都南部の金麦農場とヒーローのレベル上限15を解放した。",
      "你击败了森林狼王，并解锁第二关与英雄10级上限。最大法力只在统领试炼中提升。": "森の狼王を倒し、第2章とヒーローのレベル上限10を解放した。最大マナは統率者の試練でのみ上昇する。",
