      "已击败的节点、路线解锁和本轮奖励都会保留。之后点击“继续游戏”即可从当前进度继续。": "倒したノード、解放したルート、今回の報酬は全て保持されます。あとで「コンティニュー」を押せば現在の進行度から再開できます。",
