      "将第五关设置为前19个首领已经击败，只留下银灰狼女猎手。英雄、金币、收藏、卡组以及其他关卡存档均不会改变。": "第5章を最初の19体のボスを撃破済みの状態にし、銀灰の狼女狩人だけを残します。ヒーロー、ゴールド、コレクション、デッキ、他の章のセーブは変わりません。",
