      "第{0}关 · {1}": "第{0}試練・{1}",
      "有人说{0}永远不可能被人类接纳。可我的军籍、薪饷和选票都是真的。": "{0}が人間に受け入れられるはずがないと言う者もいる。だが私の軍籍も給料も投票権も、全て本物だ。",
      "记住报名册上的名字——{0}。我来自{1}，也认同人类建立的{2}；所以我选择加入，他们也接受了我。": "名簿の名前を覚えておけ――{0}。私は{1}の出身で、人間が築いた{2}にも共感している。だから加わることを選び、彼らも私を受け入れた。",
      "记好名字，{0}。{1}。等你退场时，至少知道是谁送你的。": "名前を覚えておけ、{0}。{1}。退場する時、誰に送り出されたかくらいは分かるようにな。",
      "我是{0}，来自{1}。我的研究是{2}；而你，是今天最有价值的实战样本。": "私は{0}、{1}の出身。私の研究は{2}。そしてあなたは、今日最も価値ある実戦標本よ。",
      "我是{0}，来自{1}。我信奉{2}。护卫队长，请用一场完整的战斗回应我。": "私は{0}、{1}の出身だ。私は{2}を信じている。護衛隊長、完全な一戦で私に応えてくれ。",
