      "萌芽古树": "芽吹く古木",
      "无视前排保护，对任意一个敌方随从造成{0}点伤害；若击杀目标，抽1张牌。": "前列の守りを無視し、任意の敵ミニオン1体に{0}ダメージを与える。倒した場合、カードを1枚引く。",
      "发射{0}枚奥术飞弹，每枚随机对一个敌方随从或敌方英雄造成1点伤害。": "アーケインミサイルを{0}発放ち、それぞれランダムな敵ミニオンか敵ヒーローに1ダメージを与える。",
      "使所有己方随从恢复至满生命，并为英雄恢复{0}点生命。": "味方ミニオン全員の体力を全回復し、ヒーローの体力を{0}回復する。",
      "英雄失去2点生命，使一个己方随从本回合获得+{0}攻击，并可以立即再次攻击。": "ヒーローは体力を2失い、味方ミニオン1体はこのターン攻撃力+{0}を得て、すぐにもう一度攻撃できる。",
      "在后排召唤一个{0}攻/{1}血的远程林影弓手，它可以立即攻击随从。": "後列に攻撃{0}/体力{1}の遠隔の林影の弓手を召喚する。すぐにミニオンを攻撃できる。",
      "所有己方前排随从永久获得+{0}生命；若前排为空，则召唤一个0攻/{1}血的圣盾卫士。": "味方の前列ミニオン全員が永続的に体力+{0}を得る。前列が空なら、攻撃0/体力{1}の聖盾の守護者を召喚する。",
      "召唤一个{0}攻/{1}血的古树幼苗；它在你每回合开始时永久获得+1/+1。": "攻撃{0}/体力{1}の古木の苗を召喚する。自分のターン開始時ごとに永続的に+1/+1を得る。",
