      "{0}陷入血怒，本回合攻击力提升至{1}，可以立即攻击。": "{0}は血怒に陥り、このターン攻撃力が{1}に上昇、すぐに攻撃できる。",
      "{0}陷入血怒，本回合攻击力提升至{1}。": "{0}は血怒に陥り、このターン攻撃力が{1}に上昇。",
