      "新英雄「{0}」将从头开始远征。之后的进度会自动保存到所选栏位。": "新たなヒーロー「{0}」が最初から遠征を始める。以後の進行は選んだスロットに自動保存される。",
      "读取后，之后的进度会自动保存到该栏位。": "ロード後、以後の進行はそのスロットに自動保存される。",
