      "麦香面包": "小麦の香りパン",
      "刚出炉的粗麦面包，谁都不会拒绝。": "焼きたての粗挽き麦パン。断る者はいない。",
      "炭烤肉串": "炭火焼き串",
      "撒满辣椒粉的炭烤肉串，哥布林最爱抢着吃。": "唐辛子をたっぷり振った炭火焼き串。ゴブリンが奪い合う大好物。",
      "金蜜松饼": "黄金蜂蜜パンケーキ",
      "淋上整勺蜂蜜的厚松饼，熊族闻到就走不动路。": "蜂蜜をたっぷりかけた厚焼きパンケーキ。熊族は匂いだけで足が止まる。",
      "月露果冻": "月露ゼリー",
      "用月潭露水凝成的清凉果冻，史莱姆会把它整个吞进身体里。": "月潭の露で固めたひんやりゼリー。スライムは丸ごと体に取り込む。",
      "炙烤带骨肉": "骨付き肉のあぶり焼き",
      "外焦里嫩的大块带骨肉，狼族会一边啃一边摇尾巴。": "外はカリッと中はジューシーな大きな骨付き肉。狼族はかじりながら尻尾を振る。",
      "猎人炖锅": "狩人の煮込み鍋",
      "炖了一整夜的浓汤，暖胃也暖心。": "一晩じっくり煮込んだ濃厚スープ。お腹も心も温まる。",
      "丰收宴席": "豊穣の宴",
      "一整桌丰盛的宴席，再倔强的俘虏也会动摇。": "卓いっぱいのごちそう。どんな頑固な捕虜も心が揺らぐ。",
      "下矿": "採掘",
      "钻进褐石矿坑挖金子，按好感等级带回金币。": "褐石の坑道で金を掘り、好感レベルに応じたゴールドを持ち帰る。",
      "种田": "畑仕事",
      "去营地外的麦田耕种，收获的麦子直接磨成面粉，补充队伍粮食。": "野営地の外の麦畑を耕す。収穫した麦は粉にして隊の食糧に。",
      "熬药": "薬の調合",
      "用身体慢慢熬出药水，给卡组里随机一张未满级的卡牌增加经验。": "体の中でじっくり薬を煮出し、デッキ内のランダムな未最大レベルのカードに経験値を与える。",
      "打猎": "狩り",
      "去林子里打猎，带回炙烤带骨肉（狼族最爱）和一些粮食。": "森で狩りをして、骨付き肉のあぶり焼き（狼族の大好物）と少しの食糧を持ち帰る。",
