      "第二关起击败的首领，其首杀奖励卡要与牢里的本人结缘（好感度{0}）后才能出战；继续投喂，每{1}点好感升一级（最高{2} Lv{3}），结缘后每高一级：随从+{4}攻击、+{5}生命，法术效果提升{6}级。最终首领的卡牌要等本关全部在押首领结缘才能使用，等级取其中最低的一位。每名首领每天（现实{7}分钟）只能投喂一次，距离新的一天还有{8}。背包里共有 {9} 份食物。": "第2章以降に倒したボスの初撃破報酬カードは、牢にいる本人と結縁（好感度{0}）してから出撃できる。食事を続けると好感{1}ごとにレベルアップ（最大{2} Lv{3}）。結縁より1レベル上がるごとにミニオンは攻撃+{4}・体力+{5}、呪文は効果+{6}レベル。最終ボスのカードは、その章の囚われのボス全員と結縁すると使え、レベルは最も低い者に合わせる。各ボスへの食事は1日（現実{7}分）に1回まで。次の日まであと{8}。バッグの食べ物は計{9}個。",
